// RGB到BGR颜色转换函数（解决红蓝颜色显示错误）
static void convert_rgb_to_bgr(uint8_t * rgb_data, int pixel_count)
{
    for (int i = 0; i < pixel_count; i++) {
        // 交换R和B字节，保持G不变
        uint8_t temp = rgb_data[i * 3 + 0];      // 保存R
        rgb_data[i * 3 + 0] = rgb_data[i * 3 + 2]; // R = B
        rgb_data[i * 3 + 2] = temp;              // B = R
        // G (rgb_data[i * 3 + 1]) 保持不变
    }
}

// 动画定时器回调函数
static void animation_timer_cb(lv_timer_t * timer)
{
    if (!is_animation_playing || !animation_img_obj) {
        return;
    }
    
    current_frame++;
    
    // 检查是否播放完成
    if (current_frame > total_frames) {
        printf("🎬 动画播放完成，返回背景图\n");
        
        // 停止动画
        is_animation_playing = false;
        if (animation_timer) {
            lv_timer_delete(animation_timer);
            animation_timer = NULL;
        }
        
        // 关闭覆盖层
        if (photo_overlay) {
            lv_obj_delete(photo_overlay);
            photo_overlay = NULL;
        }
        animation_img_obj = NULL;
        
        // 释放动态图像数据
        if (dynamic_img_dsc) {
            free(dynamic_img_dsc);
            dynamic_img_dsc = NULL;
        }
        if (dynamic_img_data) {
            jpeg_free_align(dynamic_img_data);
            dynamic_img_data = NULL;
        }
        
        return;
    }
    
    // 构建当前帧的文件路径
    char frame_path[512];
    snprintf(frame_path, sizeof(frame_path), "%s/Image%d.jpg", animation_base_path, current_frame);
    
    // 减少日志输出以提高性能，只在关键帧输出
    if (current_frame % 10 == 1 || current_frame == 1) {
        printf("🎞️ 播放第 %d/%d 帧\n", current_frame, total_frames);
    }
    
    // 加载并显示当前帧
    lv_image_dsc_t * frame_img = create_image_from_sd_jpeg(frame_path);
    if (frame_img && animation_img_obj) {
        lv_image_set_src(animation_img_obj, frame_img);
        // 强制刷新显示以减少卡顿
        lv_obj_invalidate(animation_img_obj);
    } else {
        printf("❌ 加载第 %d 帧失败\n", current_frame);
    }
}

// 获取动画文件夹中的图片数量
static int get_animation_frame_count(const char * folder_path)
{
    int max_frame = 0;
    char test_path[512];
    
    // 从 1 开始测试，找到最大的图片编号
    for (int i = 1; i <= 200; i++) {  // 最多检查200张图片
        snprintf(test_path, sizeof(test_path), "%s/Image%d.jpg", folder_path, i);
        if (safe_file_exists(test_path)) {
            max_frame = i;
        } else {
            // 连续几个文件不存在就认为结束了
            bool found_next = false;
            for (int j = i + 1; j <= i + 5 && j <= 200; j++) {
                snprintf(test_path, sizeof(test_path), "%s/Image%d.jpg", folder_path, j);
                if (safe_file_exists(test_path)) {
                    found_next = true;
                    break;
                }
            }
            if (!found_next) {
                break;
            }
        }
    }
    
    printf("📊 检测到动画帧数: %d\n", max_frame);
    return max_frame;
}

// 开始播放动画
static void start_animation(const char * folder_path)
{
    printf("\n🎬 开始播放动画: %s\n", folder_path);
    
    // 停止之前的动画或照片显示
    if (animation_timer) {
        lv_timer_delete(animation_timer);
        animation_timer = NULL;
    }
    if (photo_timer) {
        lv_timer_delete(photo_timer);
        photo_timer = NULL;
    }
    if (photo_overlay) {
        lv_obj_delete(photo_overlay);
        photo_overlay = NULL;
    }
    
    // 获取动画帧数
    total_frames = get_animation_frame_count(folder_path);
    if (total_frames <= 0) {
        printf("❌ 动画文件夹中没有找到图片文件\n");
        return;
    }
    
    // 保存基础路径
    strncpy(animation_base_path, folder_path, sizeof(animation_base_path) - 1);
    animation_base_path[sizeof(animation_base_path) - 1] = '\0';
    
    // 创建覆盖层
    photo_overlay = lv_obj_create(lv_scr_act());
    lv_obj_set_size(photo_overlay, LV_PCT(100), LV_PCT(100));
    lv_obj_set_pos(photo_overlay, 0, 0);
    lv_obj_remove_flag(photo_overlay, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_opa(photo_overlay, LV_OPA_80, LV_PART_MAIN);
    lv_obj_set_style_bg_color(photo_overlay, lv_color_black(), LV_PART_MAIN);
    lv_obj_set_style_border_width(photo_overlay, 0, LV_PART_MAIN);
    
    // 创建图片对象
    animation_img_obj = lv_image_create(photo_overlay);
    lv_obj_center(animation_img_obj);
    
    // 加载第一帧
    current_frame = 0;  // 将在定时器回调中递增到1
    is_animation_playing = true;
    
    // 创建动画定时器，使用可调节的间隔
    animation_timer = lv_timer_create(animation_timer_cb, animation_interval_ms, NULL);
    
    printf("🎯 动画设置完成，总帧数: %d，播放间隔: %dms\n", total_frames, animation_interval_ms);
}

// 简化的SD卡状态检查函数
static bool check_sd_card_status(void)
{
    printf("\n=== SD卡状态检查 ===\n");
    
    // 检查SD卡是否挂载
    struct stat st;
    if (stat("/sdcard", &st) != 0) {
        printf("❌ SD卡未挂载或 /sdcard 目录不存在\n");
        return false;
    }
    
    printf("✅ SD卡已挂载\n");
    
    // 尝试简单的目录访问
    DIR *dir = opendir("/sdcard");
    if (dir == NULL) {
        printf("❌ 无法访问SD卡根目录\n");
        return false;
    }
    
    printf("✅ 可以访问SD卡根目录\n");
    
    // 快速检查是否有内容
    struct dirent *entry;
    int file_count = 0;
    int dir_count = 0;
    
    while ((entry = readdir(dir)) != NULL && (file_count + dir_count) < 10) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        
        char full_path[512];  // 增加缓冲区大小
        snprintf(full_path, sizeof(full_path), "/sdcard/%s", entry->d_name);
        
        struct stat statbuf;
        if (stat(full_path, &statbuf) == 0) {
            if (S_ISDIR(statbuf.st_mode)) {
                printf("📁 目录: %s\n", entry->d_name);
                dir_count++;
            } else {
                printf("📄 文件: %s (大小: %ld 字节)\n", entry->d_name, statbuf.st_size);
                file_count++;
            }
        } else {
            printf("❓ 无法获取信息: %s\n", entry->d_name);
        }
    }
    
    closedir(dir);
    
    printf("📊 找到 %d 个文件和 %d 个目录\n", file_count, dir_count);
    printf("==================\n\n");
    
    return true;
}

// 安全的文件存在检查函数
static bool safe_file_exists(const char *filepath)
{
    struct stat st;
    int result = stat(filepath, &st);
    if (result != 0) {
        return false;
    }
    return S_ISREG(st.st_mode);  // 确保是常规文件
}

// 简化的图像文件搜索函数 - 只搜索根目录，避免过度访问SD卡
static void find_simple_image_files(void)
{
    printf("\n🔍 搜索根目录图像文件...\n");
    
    DIR *dir = opendir("/sdcard");
    if (dir == NULL) {
        printf("❌ 无法打开SD卡根目录\n");
        return;
    }
    
    struct dirent *entry;
    int image_count = 0;
    
    while ((entry = readdir(dir)) != NULL && image_count < 20) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        
        // 检查文件扩展名
        char *ext = strrchr(entry->d_name, '.');
        if (ext != NULL) {
            if (strcasecmp(ext, ".jpg") == 0 || 
                strcasecmp(ext, ".jpeg") == 0 || 
                strcasecmp(ext, ".png") == 0 || 
                strcasecmp(ext, ".bmp") == 0) {
                
                char full_path[512];  // 增加缓冲区大小
                snprintf(full_path, sizeof(full_path), "/sdcard/%s", entry->d_name);
                
                struct stat statbuf;
                if (stat(full_path, &statbuf) == 0) {
                    printf("🖼️ 找到图像: %s (大小: %ld 字节)\n", full_path, statbuf.st_size);
                    image_count++;
                }
            }
        }
    }
    
    closedir(dir);
    
    if (image_count == 0) {
        printf("❌ 根目录未找到图像文件\n");
    } else {
        printf("✅ 在根目录找到 %d 个图像文件\n", image_count);
    }
    printf("===================\n\n");
}

// 从SD卡读取JPEG文件并创建LVGL图像描述符
static lv_image_dsc_t * create_image_from_sd_jpeg(const char * file_path)
{
    FILE * file = NULL;
    uint8_t * jpeg_data = NULL;
    uint8_t * rgb_data = NULL;
    lv_image_dsc_t * img_dsc = NULL;
    int jpeg_size = 0;
    int rgb_size = 0;
    
    // 先释放之前的动态图像数据
    if (dynamic_img_dsc) {
        free(dynamic_img_dsc);
        dynamic_img_dsc = NULL;
    }
    if (dynamic_img_data) {
        jpeg_free_align(dynamic_img_data);
        dynamic_img_data = NULL;
    }
    
    // 打开SD卡上的JPEG文件
    // 减少日志输出以提高性能
    file = fopen(file_path, "rb");
    if (!file) {
        printf("❌ 无法打开文件: %s\n", file_path);
        return NULL;
    }
    
    // 获取文件大小
    fseek(file, 0, SEEK_END);
    jpeg_size = ftell(file);
    fseek(file, 0, SEEK_SET);
    
    if (jpeg_size <= 0) {
        printf("文件大小无效: %d\n", jpeg_size);
        fclose(file);
        return NULL;
    }
    
    // 分配内存用于JPEG数据
    jpeg_data = malloc(jpeg_size);
    if (!jpeg_data) {
        printf("无法分配JPEG数据内存\n");
        fclose(file);
        return NULL;
    }
    
    // 读取JPEG文件数据
    size_t bytes_read = fread(jpeg_data, 1, jpeg_size, file);
    fclose(file);
    
    if (bytes_read != jpeg_size) {
        printf("文件读取不完整: %zu/%d\n", bytes_read, jpeg_size);
        free(jpeg_data);
        return NULL;
    }
    
    // 使用decode.c中的增强函数解码JPEG并获取尺寸信息
    int width = 0, height = 0;
    jpeg_error_t ret = esp_jpeg_decode_one_picture_with_info(jpeg_data, jpeg_size, &rgb_data, &rgb_size, &width, &height);
    free(jpeg_data); // 释放JPEG原始数据
    
    if (ret != JPEG_ERR_OK || !rgb_data) {
        printf("JPEG解码失败，错误码: %d\n", ret);
        return NULL;
    }
    
    // 转换RGB到BGR格式以修复颜色显示问题
    int pixel_count = width * height;
    convert_rgb_to_bgr(rgb_data, pixel_count);
    
    // 创建LVGL图像描述符
    img_dsc = malloc(sizeof(lv_image_dsc_t));
    if (!img_dsc) {
        printf("无法分配图像描述符内存\n");
        jpeg_free_align(rgb_data);
        return NULL;
    }
    
    // 设置图像头部信息
    img_dsc->header.magic = LV_IMAGE_HEADER_MAGIC;
    img_dsc->header.cf = LV_COLOR_FORMAT_RGB888; // RGB888格式
    img_dsc->header.flags = 0;
    img_dsc->header.w = width;
    img_dsc->header.h = height;
    img_dsc->header.stride = width * 3; // RGB888每像素3字节
    img_dsc->header.reserved_2 = 0;
    img_dsc->data_size = rgb_size;
    img_dsc->data = rgb_data;
    img_dsc->reserved = NULL;
    
    // 保存到全局变量以便后续释放
    dynamic_img_dsc = img_dsc;
    dynamic_img_data = rgb_data;
    
    // 减少日志输出，只在第一帧显示详细信息
    static bool first_frame_info_shown = false;
    if (!first_frame_info_shown) {
        printf("✅ 图像描述符: %dx%d, 数据大小: %d\n", width, height, rgb_size);
        first_frame_info_shown = true;
    }
    return img_dsc;
}

// 通用照片显示函数
static void show_photo_overlay(const lv_image_dsc_t * photo_img)
{
    // 如果已经有照片显示，先关闭
    if (photo_overlay) {
        lv_obj_delete(photo_overlay);
        photo_overlay = NULL;
    }
    if (photo_timer) {
        lv_timer_delete(photo_timer);
        photo_timer = NULL;
    }

    // 创建覆盖层容器
    photo_overlay = lv_obj_create(lv_scr_act());
    lv_obj_set_size(photo_overlay, LV_PCT(100), LV_PCT(100));
    lv_obj_set_pos(photo_overlay, 0, 0);
    lv_obj_remove_flag(photo_overlay, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_bg_opa(photo_overlay, LV_OPA_80, LV_PART_MAIN);
    lv_obj_set_style_bg_color(photo_overlay, lv_color_black(), LV_PART_MAIN);
    lv_obj_set_style_border_width(photo_overlay, 0, LV_PART_MAIN);

    // 创建图片对象
    lv_obj_t * photo_img_obj = lv_image_create(photo_overlay);
    lv_image_set_src(photo_img_obj, photo_img);
    lv_obj_center(photo_img_obj);

    // 设置3秒定时器
    photo_timer = lv_timer_create(photo_timer_cb, 3000, NULL);
    lv_timer_set_repeat_count(photo_timer, 1);
}

